//! Internal facade consumed by the code generated by `ice-rpc-macros`.
//!
//! Groups the runtime internals the `#[service]` macro depends on, so the
//! stable public API of `ice-rpc` stays small. `#[doc(hidden)]`, and **not**
//! part of the public API: its symbols are semver-exempt for the consumers of
//! `ice-rpc`, but **not** for `ice-rpc-macros`.

// ── Node liveness ───────────────────────────────────────────────────
pub use crate::node_liveness::{
    is_pid_alive, is_provider, mark_provider, register_node_liveness_watcher,
    unregister_node_liveness_watcher, LIVENESS_POLL_MS,
};

// ── Shutdown ────────────────────────────────────────────────────────
pub use crate::shutdown::{clear_ipc_cleanup, register_ipc_cleanup};

// ── Rx vocabulary, wire header and name limits ──────────────────────
pub use crate::types::{
    channel, fmt_correlation_id, next_correlation_id, raw_pid_to_u32, service_id_of,
    unbounded_channel, EventKind, NodeId, RpcHeader, Sender, WireEvent, METHOD_NAME_LEN,
    PROTOCOL_VERSION, SERVICE_NAME_LEN,
};

// Canonical terminals behind the inherent `Observable` methods.
pub use crate::types::{collect_values, first_event};

// ── Service traits implemented by the generated code ────────────────
// `ServiceInit` stays public: it is the only one a developer implements.
pub use crate::service_traits::{HttpCallable, ServiceConsumer, ServiceLifecycle, ServiceNamed};

// ── Bootstrap / configuration ───────────────────────────────────────
pub use crate::config::setup_iceoryx2_global_config;

// ── Lifecycle ───────────────────────────────────────────────────────
// Escape hatch for contexts the macros cannot cover (N-API gateway, tests).
pub use crate::{
    global_cancel_token, init, init_without_ctrl_c, shutdown_and_release, wait_for_shutdown,
    ShutdownGuard,
};

// ── Plumbing invoked by the generated entry points ──────────────────
pub use crate::{_ProviderService, registry_cancel_token, run_provider_inner};

#[cfg(feature = "http")]
pub use crate::start_http_server;

// ── Publish/subscribe transport ─────────────────────────────────────
// Entry points used by the generated client/server.
pub use crate::transport::{
    decode_aligned, native_call, observable_to_responses, register_native_service,
    spawn_native_service, start_registered_channels, ResponseIter, ServiceDispatcher,
};

// ── Dependency re-exports used by the generated code ────────────────
pub use async_channel;
pub use async_lock;
pub use base64;
pub use futures;
pub use futures_lite;
pub use iceoryx2;
pub use log;
pub use rkyv;
pub use serde_json;
